import sys

def match_brute(s, p):
    from functools import lru_cache
    @lru_cache(None)
    def f(i, j):
        if j == len(p): return i == len(s)
        first = i < len(s) and p[j] in (s[i], '.')
        if j + 1 < len(p) and p[j + 1] == '*':
            # '*' 匹配 0 次、或 1+ 次（首字符匹配则继续）
            return f(i, j + 2) or (first and f(i + 1, j))
        return first and f(i + 1, j + 1)
    return f(0, 0)

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        sys.exit(0)
    s = lines[0].rstrip()
    p = lines[1].rstrip()
    print('true' if match_brute(s, p) else 'false')

import sys

def match_opt(s, p):
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    for j in range(2, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                # '*' 重复 0 次（看 j-2）或重复 1+ 次（看 i 是否与前一个字符匹配）
                dp[i][j] = dp[i][j - 2] or (
                    (s[i - 1] == p[j - 2] or p[j - 2] == '.') and dp[i - 1][j]
                )
            else:
                dp[i][j] = dp[i - 1][j - 1] and (s[i - 1] == p[j - 1] or p[j - 1] == '.')
    return dp[m][n]

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        sys.exit(0)
    s = lines[0].rstrip()
    p = lines[1].rstrip()
    print('true' if match_opt(s, p) else 'false')

import sys

def match_best(s, p):
    m, n = len(s), len(p)
    dp = [False] * (n + 1)
    dp[0] = True
    for j in range(2, n + 1):
        if p[j - 1] == '*':
            dp[j] = dp[j - 2]
    for i in range(1, m + 1):
        prev = dp[:]
        cur = [False] * (n + 1)
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                # dp[i][j-2] 来自当前行 cur；dp[i-1][j] 来自 prev
                v1 = cur[j - 2]
                v2 = (s[i - 1] == p[j - 2] or p[j - 2] == '.') and prev[j]
                cur[j] = v1 or v2
            else:
                cur[j] = (s[i - 1] == p[j - 1] or p[j - 1] == '.') and prev[j - 1]
        dp = cur
    return dp[n]

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        sys.exit(0)
    s = lines[0].rstrip()
    p = lines[1].rstrip()
    print('true' if match_best(s, p) else 'false')
